DROP TABLE IF EXISTS `SENSOR_READINGS`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `SENSOR_READINGS` (
  `readingId` bigint NOT NULL AUTO_INCREMENT,
  `nodeId` int NOT NULL,
  `timestamp` datetime NOT NULL,
  `temperature` decimal(5,2) DEFAULT NULL,
  `humidity` decimal(5,2) DEFAULT NULL,
  `ph` decimal(4,2) DEFAULT NULL,
  `n` decimal(5,2) DEFAULT NULL,
  `p` decimal(5,2) DEFAULT NULL,
  `k` decimal(5,2) DEFAULT NULL,
  `battery` int NOT NULL DEFAULT '100',
  PRIMARY KEY (`readingId`),
  KEY `nodeId` (`nodeId`),
  CONSTRAINT `SENSOR_READINGS_ibfk_1` FOREIGN KEY (`nodeId`) REFERENCES `NODES` (`nodeId`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=274 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

